var callSwitchSnapshot = rpc.declare({
  object: 'luci.vantage_switch',
  method: 'snapshot',
  expect: { '': {} },
});

function switchClientPort(view, client) {
  if (client.port !== 'eth0' || !view.switchSnapshot) return '';
  return view.switchSnapshot.clients[String(client.mac).toLowerCase()] || '';
}

function switchWord(zh, en) {
  return /^zh(?:[-_]|$)/i.test(document.documentElement.lang || '') ? zh : en;
}

function readSwitchSnapshot(view) {
  if (view.switchBusy) return;
  view.switchBusy = true;
  L.resolveDefault(callSwitchSnapshot(), {})
    .then(function (data) {
      view.switchSnapshot =
        data.state === 'ok' && Array.isArray(data.ports) && data.clients ? data : null;
      if (view.el && view.el.switchPorts && view.m) {
        paintSwitchPorts(view);
        view.paintHero();
        view.paintClients();
      }
    })
    .finally(function () {
      view.switchBusy = false;
    });
}

function paintSwitchPorts(view) {
  var tile = view.el.switchPorts,
    data = view.switchSnapshot;
  if (!data) {
    dom.content(tile, [
      E('div', { class: 'vt-empty-inline' }, [
        switchWord('交换机数据暂不可用', 'Switch data is unavailable'),
      ]),
    ]);
    return;
  }
  var hosts = Object.create(null);
  (view.m.wiredHosts || []).forEach(function (client) {
    var port = switchClientPort(view, client);
    if (port) (hosts[port] || (hosts[port] = [])).push(client.name);
  });
  var peak = data.ports.reduce(function (max, p) {
    return p.rate ? Math.max(max, p.rate[0], p.rate[1]) : max;
  }, 1);
  dom.content(
    tile,
    data.ports.map(function (p) {
      var mapped = hosts[p.name] || [];
      var desc =
        p.neighbor ||
        (mapped.length === 1
          ? mapped[0]
          : mapped.length
            ? mapped.length + switchWord(' 台设备', ' devices')
            : '');
      function rate(direction, title) {
        var value = p.rate ? p.rate[direction] : null;
        var bar = E('span', { class: 'vt-switch-rate-bar' });
        if (value != null) setW(bar, Math.max(2, (value * 100) / peak));
        return E('div', { class: 'vt-switch-rate', title: title }, [
          bar,
          E('span', {}, [
            (direction === 0 ? '← ' : '→ ') + (value == null ? fmt.DASH : fmt.bits(value * 8)),
          ]),
        ]);
      }
      return E(
        'div',
        { class: 'vt-switch-port' + (p.up ? '' : ' vt-switch-down'), title: mapped.join(', ') },
        [
          E('div', { class: 'vt-switch-name' }, [
            E('b', {}, [document.createTextNode(p.name)]),
            E('span', {}, [p.up ? switchWord('已连接', 'Up') : switchWord('未连接', 'Down')]),
          ]),
          E('div', { class: 'vt-switch-peer' }, [document.createTextNode(desc || fmt.DASH)]),
          rate(0, switchWord('交换机从该端口接收', 'Switch ingress')),
          rate(1, switchWord('交换机从该端口发送', 'Switch egress')),
        ],
      );
    }),
  );
}

function buildSwitchPorts(view) {
  var title = switchWord('交换机端口流量', 'Switch port traffic');
  view.el.switchPorts = E('div', { class: 'vt-switch-grid' });
  paintSwitchPorts(view);
  return E('section', { class: 'vt-tile vt-switch-tile', 'aria-label': title }, [
    E('header', { class: 'vt-tile-head' }, [
      E('h3', { class: 'vt-tile-title' }, [icon('router'), title]),
    ]),
    E('p', { class: 'vt-switch-caption' }, [
      switchWord(
        'GS728TP · ← 接收，→ 发送 · 端口总流量含局域网与上网流量',
        'GS728TP · ← ingress, → egress · totals include local and Internet traffic',
      ),
    ]),
    view.el.switchPorts,
  ]);
}

var callVantageInternet = rpc.declare({
  object: 'luci.vantage_internet',
  method: 'counters',
  expect: { '': {} },
});

function internetLabel() {
  return /^zh(?:[-_]|$)/i.test(document.documentElement.lang || '') ? '上网速率' : 'Internet rate';
}

function readInternetRates(view) {
  if (view.internetBusy) return;
  view.internetBusy = true;
  L.resolveDefault(callVantageInternet(), {})
    .then(function (next) {
      var previous = view.internetSample;
      var elapsed = previous && next.at - previous.at;
      view.internetSample = next.hosts && typeof next.at === 'number' ? next : null;
      view.internetRates = null;
      if (view.internetSample && elapsed >= 1 && elapsed <= 90) {
        var rates = Object.create(null);
        Object.keys(next.hosts).forEach(function (address) {
          var current = next.hosts[address],
            old = previous.hosts[address] || {};
          function delta(direction) {
            var count = current[direction] || 0,
              last = old[direction] || 0;
            return (Math.max(0, count - last) * 8) / elapsed;
          }
          rates[address] = { rx: delta('rx'), tx: delta('tx') };
        });
        view.internetRates = rates;
      }
      if (view.m && view.el && view.el.tbody) view.paintClients();
    })
    .finally(function () {
      view.internetBusy = false;
    });
}

function clientInternetRate(view, client) {
  if (client.vpn || client.gone || !view.internetRates || !client.ips || !client.ips.length)
    return null;
  var total = { rx: 0, tx: 0 },
    inScope = client.network === 'lan' || client.bridge === 'br-lan';
  client.ips.forEach(function (ip) {
    var r = view.internetRates[ip];
    if (r) {
      inScope = true;
      total.rx += r.rx;
      total.tx += r.tx;
    }
  });
  return inScope ? total : null;
}

function annotateUnifiClients(model, snapshot) {
  if (!snapshot) return;
  model.clients.concat(model.wiredHosts).forEach(function (client) {
    var match = snapshot[client.mac];
    if (!match || typeof match.ap !== 'string') return;
    client.unifiAp = fmt.safeText(match.ap, 64);
    var label = fmt.safeText(match.name || '', 48);
    if (!label || client.nameSource === 'alias') return;
    client.name = client.plainName = label;
    client.nameSource = 'unifi';
    client.nameSourceLabel = 'UniFi';
  });
}

function unifiApLine(client) {
  return E('div', { class: 'vt-phy vt-phy-up vt-tn' }, [
    document.createTextNode(switchWord('最近 AP · ', 'Last AP · ') + client.unifiAp),
  ]);
}

var callUnifiAps = rpc.declare({ object: 'luci.unifi_aps', method: 'list', expect: { '': {} } });

var callHomeVpn = rpc.declare({ object: 'luci.home_access', method: 'vpn', expect: { '': {} } });

function homeContext(view) {
  var raw = view.lastRaw || {},
    snapshot = view.unifiSnapshot || {};
  return homeAccess.prepare(
    raw.fdb,
    view.switchSnapshot,
    { aps: snapshot.aps, clients: view.unifiClients },
    raw.hints,
  );
}

function homeAccessLabel(kind) {
  return homeAccess.label(kind, switchWord);
}

function homeClientKinds(view, rows) {
  var selected = view.ui.accessKind || 'all';
  var kinds = ['all'].concat(homeAccess.kinds);
  var counts = { all: rows.length, wired: 0, wifi: 0, vpn: 0, unknown: 0 };
  rows.forEach(function (row) {
    counts[row.connection.kind]++;
  });
  var signature =
    selected +
    ' ' +
    kinds
      .map(function (kind) {
        return counts[kind];
      })
      .join(' ');
  if (view.kindSig === signature) return;
  view.kindSig = signature;
  dom.content(
    view.el.kinds,
    kinds.map(function (kind) {
      return E(
        'button',
        {
          type: 'button',
          class: 'vt-kind' + (kind === selected ? ' vt-kind-on' : ''),
          'aria-pressed': String(kind === selected),
          click: function () {
            view.ui.accessKind = kind;
            view.ui.chip = 'all';
            view.pickClients();
          },
        },
        [
          E('span', {}, [kind === 'all' ? _('All') : homeAccessLabel(kind)]),
          E('span', { class: 'vt-kind-n vt-tn' }, [String(counts[kind])]),
        ],
      );
    }),
  );
}

function appendHomeWifi(hero, aps, view) {
  if (!aps.length) return;
  var lan = hero.radios.find(function (branch) {
    return branch.id === 'lan';
  });
  var branch = { id: 'home-wifi', ssids: [], via: lan && lan.el };
  branch.el = E(
    'button',
    {
      type: 'button',
      class: 'vt-node vt-node-radio vt-node-net',
      click: function () {
        view.ui.accessKind = 'wifi';
        view.showWired();
      },
    },
    [
      E('span', { class: 'vt-node-body' }, [
        E('span', { class: 'vt-node-title' }, ['Wi-Fi']),
        E('span', { class: 'vt-node-sub' }, [switchWord('经 GS728TP 接入 LAN', 'LAN via GS728TP')]),
      ]),
    ],
  );
  var col = E('div', { class: 'vt-branch-ssids vt-unifi-list', 'aria-label': 'UniFi AP' });
  aps.forEach(function (ap) {
    var caption = [ap.port ? 'GS728TP · ' + ap.port : '', ap.model, ap.ip]
      .filter(Boolean)
      .join(' · ');
    var node = E('div', { class: 'vt-node vt-node-ssid vt-unifi-card', title: caption }, [
      E('span', { class: 'vt-node-body' }, [
        E('span', { class: 'vt-node-title' }, [document.createTextNode(ap.name)]),
        E('span', { class: 'vt-node-sub vt-mono' }, [document.createTextNode(caption)]),
      ]),
    ]);
    branch.ssids.push({ id: ap.ip, el: node, active: false });
    col.appendChild(node);
  });
  branch.wrap = E('div', { class: 'vt-branch vt-branch-unifi vt-home-wifi' }, [branch.el, col]);
  var position = lan ? hero.radios.indexOf(lan) + 1 : hero.radios.length;
  hero.radios.splice(position, 0, branch);
}

