function addOpenVpnBranch(model, tunnel) {
  if (
    !tunnel ||
    tunnel.name !== 'tunhome' ||
    tunnel.up !== true ||
    !Array.isArray(tunnel.ipaddrs) ||
    model.networks.some((n) => n.dev === 'tunhome')
  )
    return;
  var address = tunnel.ipaddrs.find(
    (a) => a && typeof a.address === 'string' && /^\d{1,3}(?:\.\d{1,3}){3}$/.test(a.address),
  );
  if (!address) return;
  model.networks.push({
    name: 'tunhome',
    proto: 'OpenVPN',
    dev: 'tunhome',
    up: true,
    ipv4: address.address,
  });
}

