/* Keep the LAN and its external access points side by side. */
.vt-app .vt-branch-unifi {
	grid-template-columns: clamp(84px, 34%, 108px) minmax(0, 210px);
	column-gap: 18px;
}
.vt-app .vt-branch-unifi > .vt-node-net {
	grid-column: auto;
	min-width: 0;
	padding: 6px 7px;
}
.vt-app .vt-branch-unifi > .vt-node-net .vt-node-sub {
	overflow-wrap: anywhere;
	white-space: normal;
	font-size: 0.72rem;
}
.vt-app .vt-branch-unifi > .vt-unifi-list {
	padding-left: 0;
	gap: 4px;
}
.vt-app .vt-unifi-list .vt-unifi-card {
	padding: 4px 7px;
	min-width: 0;
}
.vt-app .vt-unifi-card .vt-node-body {
	min-width: 0;
	gap: 1px;
}
.vt-app .vt-unifi-card .vt-node-title {
	display: block;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.vt-app .vt-unifi-card .vt-node-sub {
	font-size: 0.72rem;
	line-height: 1.2;
	white-space: normal;
	overflow-wrap: anywhere;
}

.vt-app .vt-switch-tile { margin-bottom: var(--vt-sp-4); }
.vt-app .vt-switch-caption { margin: 0 0 10px; color: var(--vt-muted); }
.vt-app .vt-switch-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(118px, 1fr)); gap: 7px; }
.vt-app .vt-switch-port { padding: 6px 8px; border: 1px solid var(--vt-border); border-radius: 7px; min-width: 0; }
.vt-app .vt-switch-down { opacity: .68; }
.vt-app .vt-switch-name { display: flex; align-items: center; justify-content: space-between; gap: 5px; }
.vt-app .vt-switch-name span, .vt-app .vt-switch-peer { color: var(--vt-muted); font-size: .82em; }
.vt-app .vt-switch-peer { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.vt-app .vt-switch-rate { position: relative; font-variant-numeric: tabular-nums; font-size: .9em; }
.vt-app .vt-switch-rate span { position: relative; }
.vt-app .vt-switch-rate .vt-switch-rate-bar { position: absolute; inset: 0 auto 0 0; border-radius: 2px; background: color-mix(in srgb, var(--vt-accent) 20%, transparent); }
